      "item": "S",
      "frame": "cloak-dagger-front.png",
      "fix": "Depict Marvel's Cloak as a tall young Black man engulfed by a huge flowing hooded cloak with a clearly jagged collar and a deeply shadowed face, preserving the frontal relaxed ready pose.",
      "tool": "Codex 1a"
    },
    {
      "item": "Q",
      "frame": "cloak-dagger-front.png",
      "fix": "Refine the cloak with convincing matte fabric texture, varied sculpted folds, clear edge thickness and nuanced miniature paintwork matching the quality reference's craftsmanship.",
      "tool": "Codex 1a"
    },
    {
      "item": "P",
      "frame": "cloak-dagger-front.png",
      "fix": "Use navy #1E2A44 and near-black #12161E for the cloak, dark brown #5A3B2A for visible skin, and a readable silver #B8BEC4 clasp while retaining deep hood shadows.",
